-- Módulo 64 TurnosHorarios: turnos fijos y rotativos y su asignación a los empleados.
-- Spec: docs/specs/modulo64-turnos-horarios-backend.md (§4).

CREATE TABLE "Turnos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "HoraEntrada" time without time zone NOT NULL,
    "HoraSalida" time without time zone NOT NULL,
    "CruzaMedianoche" boolean NOT NULL,
    "ToleranciaMinutos" integer NOT NULL,
    "DiasLaborables" character varying(13),
    "DiasTrabajo" integer,
    "DiasDescanso" integer,
    "FechaInicioCiclo" date,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Turnos" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Turnos_ToleranciaMinutos" CHECK ("ToleranciaMinutos" BETWEEN 0 AND 30)
);
CREATE UNIQUE INDEX "IX_Turnos_Codigo" ON "Turnos" ("Codigo");

CREATE TABLE "AsignacionesTurno" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "TurnoId" integer NOT NULL,
    "FechaInicio" date NOT NULL,
    "FechaFin" date,
    CONSTRAINT "PK_AsignacionesTurno" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AsignacionesTurno_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AsignacionesTurno_Turnos_TurnoId" FOREIGN KEY ("TurnoId") REFERENCES "Turnos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AsignacionesTurno_FechaFin" CHECK ("FechaFin" IS NULL OR "FechaFin" >= "FechaInicio")
);
CREATE INDEX "IX_AsignacionesTurno_TurnoId" ON "AsignacionesTurno" ("TurnoId");
-- H4: un solo turno por fecha; la guarda mínima ante carreras es una única asignación por empleado y fecha de inicio.
CREATE UNIQUE INDEX "IX_AsignacionesTurno_EmpleadoId_FechaInicio" ON "AsignacionesTurno" ("EmpleadoId", "FechaInicio");
